    D.motionBlurAmount = {
      dynamic: true,
      name: "Motion Blur",
      type: PZ.property.type.NUMBER,
      value: 1,
      min: 0,
      max: 1,
      step: 0.01,
      decimals: 2,
    };
  }
  if (!D.rotationX) {
    D.rotationX = {
      dynamic: true,
      name: "Rotation X (3D)",
      type: PZ.property.type.NUMBER,
      scaleFactor: Math.PI / 180,
      value: 0,
      step: 3,
      decimals: 1,
    };
  }
  if (!D.rotationY) {
    D.rotationY = {
      dynamic: true,
      name: "Rotation Y (3D)",
      type: PZ.property.type.NUMBER,
      scaleFactor: Math.PI / 180,
      value: 0,
      step: 3,
      decimals: 1,
    };
