  const patched = function (e, t, r, i) {
    if (patched.__cameraPlusAlive === false) {
      return original.call(this, e, t, r, i);
    }
    this.scene.overrideMaterial = this.overrideMaterial;
    this.envMap.render(e);
    this.motionBlur.render(e);
